package dev.metallicarts.test;
import dev.metallicarts.arts.*;
import dev.metallicarts.config.ProgressionConfig;
import dev.metallicarts.domain.*;
import dev.metallicarts.allomancy.*;
import dev.metallicarts.economy.*;
import dev.metallicarts.equipment.*;
import dev.metallicarts.feruchemy.*;
import dev.metallicarts.registry.ModRegistries;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.world.item.*;
import net.minecraft.world.InteractionHand;
import java.util.*;
public final class SurvivalGameTest {
 @GameTest public void allocationIsDeterministicAndNeverRegeneratesStolenPower(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);var policy=new ProgressionConfig(1,true,1,1,1,5,10000,false,true);var allocated=SurvivalProgression.allocation(p.getUUID(),123,policy);c.assertTrue(allocated.equals(SurvivalProgression.allocation(p.getUUID(),123,policy)),"Same character/world cannot reroll");p.setAttached(ModRegistries.PROGRESSION,allocated);p.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());p.experienceLevel=5;c.assertTrue(SurvivalProgression.awaken(p,false)&&SurvivalProgression.awaken(p,true),"Actual innate discoveries");var state=p.getAttachedOrCreate(ModRegistries.SPIRITWEB);c.assertTrue(state.grants().size()==2,"One power per art");p.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());c.assertFalse(SurvivalProgression.awaken(p,false)||SurvivalProgression.awaken(p,true),"Death/extraction cannot repeat awakening");c.succeed();}
 @GameTest public void mixedVialPreflightIsAtomicAndRejectsInvestedPreview(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);var before=ReserveLedger.credit(Spiritweb.empty(),Metal.STEEL,Spiritweb.MAX_RESERVE);p.setAttached(ModRegistries.SPIRITWEB,before);var contents=List.of(new MetalItemData(1,UUID.randomUUID(),Metal.IRON,1000,1,0,Optional.empty()),new MetalItemData(1,UUID.randomUUID(),Metal.STEEL,1000,1,0,Optional.empty()));var vial=new ItemStack(EconomyContent.ITEMS.get("mixed_vial"));vial.set(MixedVialItem.CONTENT,contents);((MixedVialItem)vial.getItem()).finishUsingItem(vial,c.getLevel(),p);c.assertTrue(vial.getCount()==1&&p.getAttachedOrCreate(ModRegistries.SPIRITWEB).equals(before),"Full second metal preserves all fuel and bottle");p.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());var bottle=((MixedVialItem)vial.getItem()).finishUsingItem(vial,c.getLevel(),p);c.assertTrue(bottle.is(Items.GLASS_BOTTLE)&&vial.isEmpty()&&p.getAttachedOrCreate(ModRegistries.SPIRITWEB).reserves().size()==2,"All ordinary metals transfer once");boolean denied=false;try{MixedVialItem.ingest(Spiritweb.empty(),List.of(new MetalItemData(1,UUID.randomUUID(),Metal.GOLD,1000,1,100,Optional.empty())));}catch(IllegalArgumentException e){denied=true;}c.assertTrue(denied,"Invested preview cannot mint compounding charge");c.succeed();}
 static ItemStack core(net.minecraft.server.level.ServerPlayer p,Metal metal){var ledger=MetalmindLedger.get(p.level().getServer());var content=new MetalmindContent(Optional.of(new StoredPower(Art.FERUCHEMY,metal,1)),List.of(),false);var lease=new AssetLease(UUID.randomUUID(),0);var a=ledger.claim(ledger.create(FeruchemicalAttribute.INVESTITURE,9000000,1,false,content).token(),lease);a=ledger.change(a.token(),lease,p.getAttachedOrCreate(ModRegistries.SPIRITWEB).identity(),100000,true);a=ledger.release(a.token(),lease);a=ledger.unseal(a.token());var item=new ItemStack(EconomyContent.item("nicrosil","ring"));item.set(ModRegistries.METALMIND,MetalmindData.of(a));return item;}
 @GameTest public void multiCoreCarrierKeepsIndependentChargeAndExclusiveLeases(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);p.setItemInHand(InteractionHand.MAIN_HAND,core(p,Metal.GOLD));p.setItemInHand(InteractionHand.OFF_HAND,core(p,Metal.IRON));Medallions.bind(p);var copy=p.getMainHandItem().copy();Medallions.equip(p,0);var ledger=MetalmindLedger.get(c.getLevel().getServer());for(int i=0;i<2;i++){var ref=ContactService.equipment(p).item(i).get(ModRegistries.METALMIND);c.assertTrue(ledger.owned(ref.token(),new AssetLease(p.getUUID(),i)).charge()==100000,"Each core keeps exact paid balance");}for(int i=0;i<2;i++)c.assertTrue(FeruchemyRuntime.act(p,new dev.metallicarts.network.ContactIntent(2,i,0,2,1),100),"Each unsealed core activates without innate Feruchemy");FeruchemyRuntime.tick(p,101);c.assertTrue(EffectivePower.strength(p,Art.FERUCHEMY,Metal.GOLD)>0&&EffectivePower.strength(p,Art.FERUCHEMY,Metal.IRON)>0,"Two distinct paid abilities coexist");for(int i=0;i<2;i++)c.assertTrue(ledger.resolve(ContactService.equipment(p).item(i).get(ModRegistries.METALMIND).token()).charge()<100000,"Each active core pays independently");FeruchemyRuntime.stop(p);p.setItemInHand(InteractionHand.MAIN_HAND,copy);boolean denied=false;try{Medallions.equip(p,4);}catch(IllegalArgumentException ex){denied=true;}c.assertTrue(denied&&ContactService.equipment(p).item(4).isEmpty(),"Copied carrier cannot double-lease any core");c.succeed();}
 @GameTest public void lerasiumRequiresExplicitCrouchConsumesBeadAndDoesNotGrantFeruchemy(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);p.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());var bead=new ItemStack(EconomyContent.ITEMS.get("lerasium_bead"));p.setItemInHand(InteractionHand.MAIN_HAND,bead);var item=(LerasiumItem)bead.getItem();item.use(c.getLevel(),p,InteractionHand.MAIN_HAND);c.assertTrue(p.getAttachedOrCreate(ModRegistries.SPIRITWEB).grants().isEmpty(),"Explicit crouch before permanent change");p.setShiftKeyDown(true);item.use(c.getLevel(),p,InteractionHand.MAIN_HAND);var s=p.getAttachedOrCreate(ModRegistries.SPIRITWEB);c.assertTrue(bead.isEmpty()&&s.grants().size()==16&&s.grants().stream().allMatch(g->g.art()==Art.ALLOMANCY),"Real bead grants Allomancy only");c.succeed();}
 @GameTest public void publicSurvivalCommandsDoNotExposeOperatorGrantCommands(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);var root=c.getLevel().getServer().getCommands().getDispatcher().getRoot();c.assertTrue(root.getChild("metallicarts-survival").canUse(p.createCommandSourceStack()),"Public progression accessible");c.assertFalse(root.getChild("metallicarts").canUse(p.createCommandSourceStack()),"Operator mutations retain permission gate");c.succeed();}
 @GameTest public void survivalAlloyRejectsInvestedInputsThenCreatesOneSpecificBead(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(EconomyContent.ITEMS.get("lerasium_bead")));var ingot=new ItemStack(EconomyContent.item("steel","ingot"));ingot.set(ModRegistries.METAL_DATA,new MetalItemData(1,UUID.randomUUID(),Metal.STEEL,1000,1,100,Optional.empty()));p.setItemInHand(InteractionHand.OFF_HAND,ingot);var commands=c.getLevel().getServer().getCommands();commands.performPrefixedCommand(p.createCommandSourceStack(),"metallicarts-survival alloy");c.assertTrue(p.getMainHandItem().is(EconomyContent.ITEMS.get("lerasium_bead"))&&p.getOffhandItem().getCount()==1,"Invested input rejected without consumption");ingot.remove(ModRegistries.METAL_DATA);commands.performPrefixedCommand(p.createCommandSourceStack(),"metallicarts-survival alloy");c.assertTrue(p.getMainHandItem().is(EconomyContent.ITEMS.get("lerasium_steel_bead"))&&p.getOffhandItem().isEmpty(),"One pure bead and ingot make one typed alloy");p.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());p.setShiftKeyDown(true);((LerasiumItem)p.getMainHandItem().getItem()).use(c.getLevel(),p,InteractionHand.MAIN_HAND);var state=p.getAttachedOrCreate(ModRegistries.SPIRITWEB);c.assertTrue(state.grants().size()==1&&state.strength(Art.ALLOMANCY,Metal.STEEL)==2,"Alloy grants only its associated art/metal");c.succeed();}
}

